import { BaseSequencer } from 'vitest/node'
import { writeFileSync } from 'node:fs'

export default class DiagnosticOrder extends BaseSequencer {
  async sort(specifications) {
    const order = process.env.DIAGNOSTIC_ORDER === 'order-a'
      ? ['image-crash.test.ts', 'image-generation.test.ts']
      : ['image-generation.test.ts', 'image-crash.test.ts']
    if (specifications.length !== 2) throw new Error('Diagnostic must collect exactly two files')
    for (const spec of specifications) {
      if (!order.some((name) => spec.moduleId.endsWith(`/apps/cli/test/${name}`)))
        throw new Error('Unexpected diagnostic file')
    }
    const result = [...specifications].sort((a, b) =>
      order.findIndex((name) => a.moduleId.endsWith(`/${name}`)) -
      order.findIndex((name) => b.moduleId.endsWith(`/${name}`)))
    writeFileSync('/evidence/planned-order.json', JSON.stringify(result.map((spec) => spec.moduleId)))
    return result
  }
}

